class Solution {
  public int bitRibbonsTotalReceipt(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){int count=0;while(x!=0){x&=x-1;count++;}out.add(count);}}
    int answer=0;for(int x:out)answer+=x;return answer;
  }
}
